/**
 * Universe loader: the worker never touches the DB — it reads the committed
 * snapshot worker/universe.json (regenerated by the cloud agent when the
 * universe changes; regenerate: npx tsx scripts/export-worker-universe.mts).
 */
import { readFileSync } from "node:fs";
import path from "node:path";

export interface UniverseEntry {
  cik: number;
  ticker: string;
  name: string;
  gdeltQuery: string;
}

export function loadUniverse(): UniverseEntry[] {
  const file = path.resolve(import.meta.dirname, "..", "universe.json");
  const rows = JSON.parse(readFileSync(file, "utf8")) as UniverseEntry[];
  return rows.filter((r) => r.cik && r.ticker);
}
